'use strict';
function accountPasswordIcon(visible){return '<svg viewBox="0 0 24 24" aria-hidden="true" focusable="false" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><path d="M2 12s3.6-7 10-7 10 7 10 7-3.6 7-10 7S2 12 2 12Z"/><circle cx="12" cy="12" r="3"/>'+(visible?'<path d="m3 3 18 18"/>':'')+'</svg>'}
function accountWirePasswords(root=document){for(const input of root.querySelectorAll('input[type="password"]')){if(input.dataset.visibilityWired)return;input.dataset.visibilityWired='1';if(!input.id)input.id='password-'+uid();const label=input.closest('label'),name=label?.childNodes[0]?.textContent?.trim()||'senha',row=document.createElement('div');input.setAttribute('aria-label',name);row.className='password-entry';input.before(row);row.append(input);const button=document.createElement('button');button.type='button';button.className='password-visibility';button.setAttribute('aria-controls',input.id);const paint=()=>{const visible=input.type!=='password',action=(visible?'Ocultar ':'Mostrar ')+name.toLocaleLowerCase('pt-BR');button.innerHTML=accountPasswordIcon(visible);button.setAttribute('aria-label',action);button.title=action};paint();button.addEventListener('mousedown',e=>e.preventDefault());button.addEventListener('click',()=>{input.type=input.type==='password'?'text':'password';paint()});row.append(button)}}
const originalAccountAccess=renderNovaAccess;renderNovaAccess=function(error=''){originalAccountAccess(error);const form=document.getElementById('nova-access-form');if(form&&novaAuth.stage==='login'){let remembered='';try{remembered=localStorage.getItem('nova-remembered-login')||''}catch{}if(remembered&&!novaAuth.username)form.elements.username.value=remembered;const submit=form.querySelector('[type="submit"]');submit.insertAdjacentHTML('beforebegin',`<label class="remember-access"><input type="checkbox" name="rememberSession" ${remembered?'checked':''}><span>Manter login</span></label><p class="remember-access-help">Por até 30 dias. Use somente em um aparelho pessoal. A senha não é guardada pelo app.</p>`);form.addEventListener('submit',()=>{try{if(form.elements.rememberSession.checked)localStorage.setItem('nova-remembered-login',form.elements.username.value.trim());else localStorage.removeItem('nova-remembered-login')}catch{}},{capture:true})}accountWirePasswords(document)};
const accountPasswordObserver=new MutationObserver(()=>accountWirePasswords(document));for(const id of ['app','modal']){const element=document.getElementById(id);if(element)accountPasswordObserver.observe(element,{childList:true,subtree:true})}accountWirePasswords(document);
